"""SCMOVS update: voting now starts and ends ON TIME (within about a second of the set time).

What was wrong: the background check only woke up every 15 seconds, so an election could open or close up to ~15 seconds
late, and nothing told the people looking at the screen.

What it does now
  * The background checker runs right after the app starts (catching up on anything that came due while the app was off),
    then sleeps until the exact next start/end moment. It also wakes up the instant an election is scheduled, its dates are
    edited, a candidate is approved, or positions change.
  * Checking on page loads is faster too (every 2 seconds instead of 10).
  * The admin election page and the student "My Elections" page REFRESH THEMSELVES at the moment voting starts or ends
    (the countdown uses the server clock, so a wrong clock or time zone on the device cannot make it early or late).
  * If a scheduled election's time arrives but it cannot open (for example a candidate is still pending), the election page
    now says why, in red. The system keeps trying and opens it the moment the problem is fixed.

NO database change is needed.

HOW TO USE
  1. Put this file in your project folder (the folder that contains run.py).
  2. In PowerShell, inside that folder, run:   python apply_ontime_update.py
  3. Restart the app (python run.py).   <-- required: the checker only restarts with the app.

Your current copy of every file it replaces is saved first in _update_backup/ (same sub-folders).
"""
import base64
import os
import shutil
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
FILES = {
    'app/candidates/services.py': "",
    'app/elections/auto_close.py': "",
    'app/elections/routes.py': "",
    'app/elections/services.py': "",
    'app/voting/routes.py': "",
    'app/voting/services.py': "",
    'templates/elections/detail.html': "",
    'templates/voting/list.html': "",
    'tests/run_all.sh': "",
    'tests/test_auto_timing.py': "",
}


def main():
    if not os.path.isfile(os.path.join(ROOT, "run.py")) or not os.path.isdir(os.path.join(ROOT, "app")):
        print("STOP: put this file in your project folder (the one that has run.py and the app folder), then run it again.")
        sys.exit(1)
    auto_close = os.path.join(ROOT, "app", "elections", "auto_close.py")
    if not os.path.isfile(auto_close) or "open_due_elections" not in open(auto_close, encoding="utf-8").read():
        print("STOP: this update builds on apply_autostart_update.py (and apply_big_update.py before it). Apply those first.")
        sys.exit(1)
    for rel, encoded in FILES.items():
        target = os.path.join(ROOT, *rel.split("/"))
        if os.path.isfile(target):
            saved = os.path.join(ROOT, "_update_backup", *rel.split("/"))
            os.makedirs(os.path.dirname(saved), exist_ok=True)
            if not os.path.exists(saved):
                shutil.copy2(target, saved)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as handle:
            handle.write(base64.b64decode(encoded))
        print("  updated", rel)
    print("\nDone. NOW RESTART THE APP (stop it with Ctrl+C, then: python run.py).")


if __name__ == "__main__":
    main()
